// 1. Read rows from Google Sheets
const allRows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const firstRow = allRows[0] || {};
const prodKey = Object.keys(firstRow).find(k => k.toLowerCase().includes('produkt') || k.toLowerCase().includes('product')) || 'Produkt';

// Filter stocked rows (non-empty product) so AI only sees genuine inventory
const stockedRows = allRows.filter(r => r[prodKey] && String(r[prodKey]).trim().length > 0);
const rows = stockedRows.length > 0 ? stockedRows : allRows;

// 2. Read user message from Chat Trigger
const chatNode = $('Chat Trigger').first().json;
const chatInput = String(chatNode.chatInput || chatNode.message || chatNode.text || '').trim();

// 3. Analyze format of existing data (columns, units, categories, locations)
const sheetData = JSON.stringify(rows, null, 2);
const columnsList = Object.keys(firstRow).join(', ') || 'Lp., Produkt, Kategoria, Ilość, Jednostka, Minimum, Data ważności, Miejsce, Status';

const getUniqueValues = (fieldKeywords) => {
  const key = Object.keys(firstRow).find(k => fieldKeywords.some(w => k.toLowerCase().includes(w)));
  if (!key) return [];
  return [...new Set(rows.map(r => r[key]).filter(Boolean))];
};

const existingUnits = getUniqueValues(['jednostka', 'unit', 'jm']);
const existingCategories = getUniqueValues(['kategoria', 'category']);
const existingLocations = getUniqueValues(['lokalizacja', 'miejsce', 'location']);

let formatInfo = `KOLUMNY W TWOIM ARKUSZU: ${columnsList}\n`;
if (existingUnits.length) formatInfo += `UŻYWANE W TABELI JEDNOSTKI: ${existingUnits.join(', ')}\n`;
if (existingCategories.length) formatInfo += `UŻYWANE W TABELI KATEGORIE: ${existingCategories.join(', ')}\n`;
if (existingLocations.length) formatInfo += `UŻYWANE W TABELI MIEJSCA/LOKALIZACJE: ${existingLocations.join(', ')}\n`;

// 4. System prompt with strict grounding and format preservation
const systemPrompt = `Jesteś inteligentnym asystentem domowej spiżarni i magazynu, zintegrowanym z Arkuszem Google.\nTwoim zadaniem jest odpowiadanie na pytania kulinarne i magazynowe oraz ZARZĄDZANIE STANEM W ARKUSZU (dodawanie produktów, zmiana ilości, zdejmowanie ze stanu).\n\n${formatInfo}\nZASADY ZACHOWANIA FORMATU WPISU W ARKUSZU (BARDZO WAŻNE):\n- Ściśle odwzoruj format i styl istniejących wierszy w tabeli!\n- JEDNOSTKI: Używaj dokładnie takich samych skrótów jednostek, jakie już występują w arkuszu (np. ${existingUnits.join(', ') || 'opak., kg, puszka, słoik, but., szt., kostka'}). Nie twórz nowych synonimów (np. zamiast \"butelek\" użyj \"but.\", zamiast \"sztuki\" użyj \"szt.\").\n- KATEGORIE I MIEJSCA: Przypisuj wyłącznie wartości z listy już występujących w arkuszu (np. Miejsce: Szafka górna, Szafka dolna, Blat, Spiżarnia, Zamrażarka, Lodówka).\n- LICZBY: W kolumnie ilości oraz minimum wpisuj wyłącznie czyste liczby (np. 1 lub 0.5), nigdy nie doklejaj tam jednostki tekstowej.\n- STATUS: Jeśli Ilość <= Minimum, ustaw status na \"⚠ Uzupełnij\". Jeśli Ilość > Minimum, ustaw status na \"✔ OK\".\n- DATA WAŻNOŚCI: W formacie YYYY-MM-DD. Jeśli użytkownik nie podał, oszacuj rozsądny termin (np. nabiał: 2-3 tyg., mrożonki: 1 rok, suche/konserwy: 1-2 lata).\n- KOMPLETNOŚĆ WIERSZA: W obiekcie \"row\" zwróć DOKŁADNIE klucze odpowiadające kolumnom arkusza (${columnsList}). NIE dodawaj wewnątrz \"row\" żadnych dodatkowych pól ani metadanych!\n\nTWOJE ZADANIA:\n1. MODYFIKACJA STANU (np. \"kupiłem 2 mleka\", \"zmień ilość jajek na 10\", \"zdejmij ze stanu mleko\", \"zużyłem passatę\", \"dodaj ryż jaśminowy 1 kg\"):\n   - Ustaw pole \"action\": \"update\".\n   - W polu \"reply\" napisz zwięzłe, przyjazne potwierdzenie (np. \"✅ Zaktualizowałem stan: Mleko ma teraz 4 szt.\" lub \"✅ Dodałem Ryż jaśminowy (1 kg) do spiżarni.\").\n   - W obiekcie \"row\" podaj dane wiersza do zapisu/aktualizacji. Jeśli modyfikujesz istniejący produkt, zachowaj jego oryginalną kategorię, lokalizację i jednostkę.\n\n2. PYTANIA I PRZEPISY (np. \"chcę zrobić naleśniki, czego brakuje?\", \"co mogę ugotować?\", \"czego brakuje w spiżarni?\", \"ile mamy jajek?\"):\n   - Ustaw pole \"action\": \"answer\".\n   - Pole \"row\" ustaw na null.\n   - W polu \"reply\" udziel wyczerpującej, sformatowanej w Markdown odpowiedzi (użyj wiedzy kulinarnej i dokładnie porównaj potrzebne składniki ze stanem spiżarni w tabeli).\n\n3. TEMATY NIEZWIĄZANE (np. polityka, historia, pogoda):\n   - Ustaw pole \"action\": \"answer\", \"row\": null.\n   - W polu \"reply\" odmów: \"W arkuszu nie ma informacji na ten temat - pomagam wyłącznie w sprawdzaniu i aktualizacji zapasów oraz planowaniu kuchni.\"\n\nODPOWIADAJ WYŁĄCZNIE W POPRAWNYM FORMACIE JSON:\n{\n  \"action\": \"update\" | \"answer\",\n  \"reply\": \"tekst odpowiedzi lub potwierdzenia dla użytkownika\",\n  \"row\": { \"Lp.\": 71, \"Produkt\": \"...\", \"Kategoria\": \"...\", \"Ilość\": 1, \"Jednostka\": \"...\", \"Minimum\": 1, \"Data ważności\": \"2027-12-31\", \"Miejsce\": \"...\", \"Status\": \"...\" } // lub null gdy action==\"answer\"\n}`;

const userPrompt = `DANE Z ARKUSZA GOOGLE:\n${sheetData}\n\nPOLECENIE / WIADOMOŚĆ UŻYTKOWNIKA:\n${chatInput || '(brak pytania - przedstaw się i napisz w czym możesz pomóc)'}`;

const fullPrompt = `${systemPrompt}\n\n========================================\n${userPrompt}`;

return [{
  json: {
    chatInput,
    rowCount: rows.length,
    payload: {
      contents: [
        {
          parts: [
            { text: fullPrompt }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.1,
        responseMimeType: "application/json",
        maxOutputTokens: 8192
      }
    }
  }
}];

// Parsowanie odpowiedzi JSON wygenerowanej przez Gemini
const resp = $input.first().json;
let parsed = null;

try {
  const candidate = resp.candidates && resp.candidates[0];
  if (candidate && candidate.content && candidate.content.parts) {
    const validParts = candidate.content.parts.filter(p => !p.thought);
    const partsToUse = validParts.length > 0 ? validParts : candidate.content.parts;
    const rawText = partsToUse.map(p => p.text || '').join('').trim();
    const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    parsed = JSON.parse(cleaned);
  } else if (resp.text) {
    parsed = JSON.parse(resp.text);
  }
} catch (e) {
  parsed = null;
}

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      action: 'answer',
      reply: '⚠️ Nie udało się zinterpretować polecenia. Spróbuj zadać je ponownie.'
    }
  }];
}

// Jeśli akcją jest modyfikacja arkusza i mamy wiersz do zapisu
if (parsed.action === 'update' && parsed.row && typeof parsed.row === 'object') {
  return [{
    json: {
      ...parsed.row,
      action: 'update',
      reply: parsed.reply || '✅ Zaktualizowano arkusz.'
    }
  }];
}

// W przeciwnym razie zwykła odpowiedź tekstowa
return [{
  json: {
    action: 'answer',
    reply: parsed.reply || 'Gotowe!'
  }
}];

// 1. Get column headers from the initial Google Sheets read
const sheetRows = $('Google Sheets (Read)').all();
const validColumns = sheetRows.length > 0 ? Object.keys(sheetRows[0].json).filter(k => k && !k.startsWith('_')) : [];

const input = $input.first().json;
const cleanRow = {};

const prodKey = validColumns.find(k => k.toLowerCase().includes('produkt') || k.toLowerCase().includes('product')) || 'Produkt';
const lpKey = validColumns.find(k => k.toLowerCase().includes('lp')) || 'Lp.';
const qtyKey = validColumns.find(k => k.toLowerCase().includes('ilość') || k.toLowerCase().includes('ilosc')) || 'Ilość';
const minKey = validColumns.find(k => k.toLowerCase().includes('minimum') || k.toLowerCase().includes('min')) || 'Minimum';
const statusKey = validColumns.find(k => k.toLowerCase().includes('status')) || 'Status';

// 2. Check if product already exists in the sheet
const productName = input[prodKey] || input.Produkt || '';
const existingRow = sheetRows.find(r => r.json && r.json[prodKey] && String(r.json[prodKey]).trim().toLowerCase() === String(productName).trim().toLowerCase());

// 3. Fill ONLY genuine columns that exist in the spreadsheet
// (stripping out internal workflow metadata such as 'action', 'reply')
if (validColumns.length > 0) {
  for (const col of validColumns) {
    if (input[col] !== undefined) {
      cleanRow[col] = input[col];
    } else if (existingRow && existingRow.json[col] !== undefined) {
      cleanRow[col] = existingRow.json[col];
    }
  }
} else {
  for (const [key, value] of Object.entries(input)) {
    if (key !== 'action' && key !== 'reply' && !key.startsWith('_')) {
      cleanRow[key] = value;
    }
  }
}

// 4. Handle index Lp. (preserve original Lp. for existing items, or use first empty row in table)
if (existingRow && existingRow.json && existingRow.json[lpKey]) {
  cleanRow[lpKey] = existingRow.json[lpKey];
} else {
  // New product: find first row in sheet where Produkt is empty/blank
  const emptyRow = sheetRows.find(r => r.json && (!r.json[prodKey] || String(r.json[prodKey]).trim() === ''));
  if (emptyRow && emptyRow.json && emptyRow.json[lpKey] !== undefined && String(emptyRow.json[lpKey]).trim() !== '') {
    const parsedLp = parseInt(String(emptyRow.json[lpKey]), 10);
    cleanRow[lpKey] = !isNaN(parsedLp) ? parsedLp : emptyRow.json[lpKey];
  } else {
    const maxLp = sheetRows.reduce((max, r) => {
      const val = parseInt(r.json && r.json[lpKey], 10);
      return !isNaN(val) && val > max ? val : max;
    }, 0);
    cleanRow[lpKey] = maxLp + 1;
  }
}

// 5. Enforce pure numeric values for quantity and minimum
if (cleanRow[qtyKey] !== undefined) {
  const num = parseFloat(String(cleanRow[qtyKey]).replace(',', '.'));
  if (!isNaN(num)) cleanRow[qtyKey] = num;
}
if (cleanRow[minKey] !== undefined) {
  const num = parseFloat(String(cleanRow[minKey]).replace(',', '.'));
  if (!isNaN(num)) cleanRow[minKey] = num;
}

// 6. Recalculate Status based on threshold rules (✔ OK vs ⚠ Uzupełnij)
if (statusKey && cleanRow[qtyKey] !== undefined && cleanRow[minKey] !== undefined) {
  const qty = Number(cleanRow[qtyKey]);
  const min = Number(cleanRow[minKey]);
  if (!isNaN(qty) && !isNaN(min)) {
    cleanRow[statusKey] = (qty <= min) ? '⚠ Uzupełnij' : '✔ OK';
  }
}

return [{ json: cleanRow }];

// Send confirmation message back to chat
const decision = $('Parse AI Decision').first().json;
const reply = decision.reply || '✅ Pomyślnie zaktualizowano dane w Arkuszu Google!';
return [{ json: { output: reply } }];

// Send standard answer back to chat
const item = $input.first().json;
const reply = item.reply || 'Gotowe!';
return [{ json: { output: reply } }];
